  1	import type { IncomingMessage, ServerResponse } from 'node:http';
  2	import * as fs from 'node:fs';
  3	import * as path from 'node:path';
  4	import type { Router } from '../router.js';
  5	import type { WorkspaceManager } from '../../models/workspace/workspace.manager.js';
  6	import type { WorkspaceOrchestrator } from '../../orchestration/workspace-orchestrator.js';
  7	import type { ProjectManager } from '../../models/project/project.manager.js';
  8	import type { AppConfig } from '../../config/config.types.js';
  9	import type { ErrorLogManager } from '../../error-log/error-log.manager.js';
 10	import type { WorkspaceInfo } from '../../models/workspace/workspace.types.js';
 11	import { NotFoundError } from '../../errors.js';
 12	import { parseJsonBody, sendJson, sendError, isPlainObject } from '../requestUtils.js';
 13	import { generateWorkspaceFile, getWorkspaceFilePath } from '../../orchestration/vscode-workspace.js';
 14	import { checkWorkspaceHealth } from '../../orchestration/workspace-health.js';
 15	import { launchApplication } from '../app-launcher.js';
 16	
 17	// ---------------------------------------------------------------------------
 18	// Route registration
 19	// ---------------------------------------------------------------------------
 20	
 21	/**
 22	 * Registers workspace routes for the `/api/projects/:id/workspaces` resource
 23	 * group on the provided `Router` instance.
 24	 *
 25	 * Handlers delegate to the supplied `WorkspaceManager`, `ProjectManager`,
 26	 * and (on launch failure) `ErrorLogManager`, mapping results or errors to the
 27	 * appropriate HTTP status codes:
 28	 *
 29	 * | Method | Path                                                              | Success | Failure     |
 30	 * |--------|-------------------------------------------------------------------|---------|-------------|
 31	 * | GET    | /api/projects/:id/workspaces                                     | 200     | 404         |
 32	 * | POST   | /api/projects/:id/workspaces                                     | 201     | 400/404     |
 33	 * | GET    | /api/projects/:id/workspaces/:wid                                | 200     | 404         |
 34	 * | PUT    | /api/projects/:id/workspaces/:wid                                | 200     | 400/404     |
 35	 * | PUT    | /api/projects/:id/workspaces/:wid/rename                         | 200     | 400/404     |
 36	 * | DELETE | /api/projects/:id/workspaces/:wid                                | 204     | 404         |
 37	 * | POST   | /api/projects/:id/workspaces/:wid/setup                          | 200     | 400/404/500 |
 38	 * | GET    | /api/projects/:id/workspaces/:wid/health                         | 200     | 404         |
 39	 * | POST   | /api/projects/:id/workspaces/:wid/regenerate-workspace-file      | 200     | 400/404/500 |
 40	 * | POST   | /api/projects/:id/workspaces/:wid/launch/vscode                  | 200     | 400/404/500 |
 41	 * | POST   | /api/projects/:id/workspaces/:wid/launch/github-desktop/:rid     | 200     | 400/404/500 |
 42	 */
 43	export function registerWorkspaceRoutes(
 44	    router: Router,
 45	    workspaceManager: WorkspaceManager,
 46	    workspaceOrchestrator: WorkspaceOrchestrator,
 47	    appConfig: AppConfig,
 48	    projectManager: ProjectManager,
 49	    errorLogManager: ErrorLogManager,
 50	    /**
 51	     * Overrides the default `launchApplication` function.
 52	     *
 53	     * **For testing only.** Production callers must not pass this argument.
 54	     * When omitted, the real `launchApplication` (from `app-launcher.ts`) is used.
 55	     *
 56	     * @param command - Application command name (e.g. `'code'`, `'github'`).
 57	     * @param args    - Arguments passed to the spawned process.
 58	     * @returns       A Promise that resolves when the application launches successfully,
 59	     *                or rejects with an `Error` if the OS-level spawn fails.
 60	     */
 61	    launchFn: (command: string, args: string[]) => Promise<void> = launchApplication,
 62	): void {
 63	
 64	    // Helper: compute absolute workspace folder path.
 65	    function workspaceFolder(projectId: string, workspaceId: string): string {
 66	        return path.join(appConfig.projectsFolder, projectId, workspaceId);
 67	    }
 68	
 69	    // Helper: augment a WorkspaceInfo with an `Initialized` boolean and `FolderPath` string.
 70	    function withInitialized<T extends { ProjectID: string; WorkspaceID: string }>(ws: T): T & { Initialized: boolean; FolderPath: string } {
 71	        const wsFolder = workspaceFolder(ws.ProjectID, ws.WorkspaceID);
 72	        return { ...ws, Initialized: fs.existsSync(wsFolder), FolderPath: wsFolder };
 73	    }
 74	
 75	    // Helper: look up a workspace by project/workspace ID and send a 404 response if
 76	    // it does not exist (or the project is unknown). Returns the WorkspaceInfo on
 77	    // success, or undefined when a 404 has already been sent to the client.
 78	    function resolveWorkspace(
 79	        res: ServerResponse,
 80	        projectId: string,
 81	        workspaceId: string,
 82	    ): WorkspaceInfo | undefined {
 83	        try {
 84	            const ws = workspaceManager.getById(projectId, workspaceId);
 85	            if (ws === undefined) {
 86	                sendError(res, 404, `Workspace "${workspaceId}" not found in project "${projectId}".`);
 87	                return undefined;
 88	            }
 89	            return ws;
 90	        } catch (err) {
 91	            sendError(res, 404, err instanceof Error ? err.message : 'Not found.');
 92	            return undefined;
 93	        }
 94	    }
 95	
 96	    // ------------------------------------------------------------------
 97	    // GET /api/projects/:id/workspaces — list all workspaces
 98	    // ------------------------------------------------------------------
 99	    router.get('/api/projects/:id/workspaces', (
100	        _req: IncomingMessage,

101	        res: ServerResponse,
102	        params: Record<string, string>,
103	    ): void => {
104	        try {
105	            const workspaces = workspaceManager.list(params['id']);
106	            sendJson(res, 200, workspaces.map(withInitialized));
107	        } catch (err) {
108	            if (err instanceof NotFoundError) {
109	                sendError(res, 404, err.message);
110	            } else {
111	                sendError(res, 500, 'Internal server error.');
112	            }
113	        }
114	    });
115	
116	    // ------------------------------------------------------------------
117	    // POST /api/projects/:id/workspaces — create a workspace
118	    // ------------------------------------------------------------------
119	    router.post('/api/projects/:id/workspaces', async (
120	        req: IncomingMessage,
121	        res: ServerResponse,
122	        params: Record<string, string>,
123	    ): Promise<void> => {
124	        let body: unknown;
125	        try {
126	            body = await parseJsonBody(req);
127	        } catch (err) {
128	            sendError(res, 400, err instanceof Error ? err.message : 'Invalid request body.');
129	            return;
130	        }
131	
132	        if (!isPlainObject(body)) {
133	            sendError(res, 400, 'Request body must be a JSON object.');
134	            return;
135	        }
136	
137	        const { workspaceId, description } = body as {
138	            workspaceId?: unknown;
139	            description?: unknown;
140	        };
141	
142	        if (typeof workspaceId !== 'string' || workspaceId.trim() === '') {
143	            sendError(res, 400, 'Missing required field: workspaceId (non-empty string).');
144	            return;
145	        }
146	
147	        const desc = typeof description === 'string' ? description : undefined;
148	
149	        try {
150	            const created = workspaceManager.create(params['id'], workspaceId.trim(), desc);
151	            sendJson(res, 201, created);
152	        } catch (err) {
153	            const msg = err instanceof Error ? err.message : 'Could not create workspace.';
154	            const is404 = err instanceof NotFoundError;
155	            sendError(res, is404 ? 404 : 400, msg);
156	        }
157	    });
158	
159	    // ------------------------------------------------------------------
160	    // GET /api/projects/:id/workspaces/:wid — get one workspace
161	    // ------------------------------------------------------------------
162	    router.get('/api/projects/:id/workspaces/:wid', (
163	        _req: IncomingMessage,
164	        res: ServerResponse,
165	        params: Record<string, string>,
166	    ): void => {
167	        const workspace = resolveWorkspace(res, params['id'], params['wid']);
168	        if (workspace === undefined) return;
169	        sendJson(res, 200, withInitialized(workspace));
170	    });
171	
172	    // ------------------------------------------------------------------
173	    // PUT /api/projects/:id/workspaces/:wid — update workspace description
174	    // ------------------------------------------------------------------
175	    router.put('/api/projects/:id/workspaces/:wid', async (
176	        req: IncomingMessage,
177	        res: ServerResponse,
178	        params: Record<string, string>,
179	    ): Promise<void> => {
180	        let body: unknown;
181	        try {
182	            body = await parseJsonBody(req);
183	        } catch (err) {
184	            sendError(res, 400, err instanceof Error ? err.message : 'Invalid request body.');
185	            return;
186	        }
187	
188	        if (!isPlainObject(body)) {
189	            sendError(res, 400, 'Request body must be a JSON object.');
190	            return;
191	        }
192	
193	        const { description } = body as { description?: unknown };
194	
195	        if (typeof description !== 'string') {
196	            sendError(res, 400, 'Missing required field: description (string).');
197	            return;
198	        }
199	
200	        try {
201	            const updated = workspaceManager.update(params['id'], params['wid'], { Description: description });
202	            sendJson(res, 200, updated);
203	        } catch (err) {
204	            const msg = err instanceof Error ? err.message : 'Not found.';
205	            const is404 = err instanceof NotFoundError;
206	            sendError(res, is404 ? 404 : 400, msg);
207	        }
208	    });
209	
210	    // ------------------------------------------------------------------
211	    // PUT /api/projects/:id/workspaces/:wid/rename — rename a workspace
212	    // ------------------------------------------------------------------
213	    router.put('/api/projects/:id/workspaces/:wid/rename', async (
214	        req: IncomingMessage,
215	        res: ServerResponse,
216	        params: Record<string, string>,
217	    ): Promise<void> => {
218	        let body: unknown;
219	        try {
220	            body = await parseJsonBody(req);
221	        } catch (err) {
222	            sendError(res, 400, err instanceof Error ? err.message : 'Invalid request body.');
223	            return;
224	        }
225	
226	        if (!isPlainObject(body)) {
227	            sendError(res, 400, 'Request body must be a JSON object.');
228	            return;
229	        }
230	
231	        const { newId } = body as { newId?: unknown };
232	
233	        if (typeof newId !== 'string' || newId.trim() === '') {
234	            sendError(res, 400, 'Missing required field: newId (non-empty string).');
235	            return;
236	        }
237	
238	        try {
239	            const renamed = workspaceManager.rename(params['id'], params['wid'], newId.trim());
240	            sendJson(res, 200, renamed);
241	        } catch (err) {
242	            const msg = err instanceof Error ? err.message : 'Could not rename workspace.';
243	            const is404 = err instanceof NotFoundError;
244	            sendError(res, is404 ? 404 : 400, msg);
245	        }
246	    });
247	
248	    // ------------------------------------------------------------------
249	    // DELETE /api/projects/:id/workspaces/:wid — delete a workspace
250	    // ------------------------------------------------------------------
251	    router.delete('/api/projects/:id/workspaces/:wid', (
252	        _req: IncomingMessage,
253	        res: ServerResponse,
254	        params: Record<string, string>,
255	    ): void => {
256	        try {
257	            workspaceManager.remove(params['id'], params['wid']);
258	        } catch (err) {
